#include <linux/fs.h>
#include <linux/blkdev.h>
#include <linux/kernel.h>

struct block_device *get_block_device(dev_t dev, struct super_block *sb) {
    struct block_device *bdev;
    int mode = FMODE_READ | FMODE_WRITE | FMODE_EXCL;

    bdev = blkdev_get(dev, mode, sb);
    if (IS_ERR(bdev)) {
        pr_err("Failed to get block device for dev %d\n", dev);
        return NULL;
    }

    return bdev;
}

