#include <linux/fs.h>
#include <linux/genhd.h>
#include <linux/uaccess.h>
#include <linux/printk.h>

struct block_device *get_block_device_by_dev(dev_t dev, struct super_block *sb) {
    struct block_device *bdev;
    int mode = FMODE_READ | FMODE_WRITE | FMODE_EXCL;

    bdev = open_by_devnum(dev, mode);
    if (IS_ERR(bdev)) {
        pr_err("Failed to open block device for dev %d, error: %ld\n", dev, PTR_ERR(bdev));
        return NULL;
    }

    return bdev;
}
